packages.clientCode:
return {
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    const locale = ctx.get('locale')
    if (locale !== undefined) {
      ctx.effect(() => {
        try {
          return locale.register('usage-stats', {
            zh: { title: '使用统计', total: '累计 Token', empty: '暂无数据' },
            en: { title: 'Usage', total: 'Total tokens', empty: 'No data' },
          })
        } catch {
          return
        }
      })
    }
    const t = locale === undefined ? (key) => key : locale.bind('usage-stats')

    ctx.effect(() => slots.inject('settings.section', () => slots.register(
      {
        name: 'settings.section',
        id: 'usage-stats',
        order: 25,
        label: () => t('title'),
      },
      () => React.createElement('div', { 'data-usage-stats-fixture': 'panel' },
        React.createElement('span', { 'data-usage-stats-fixture': 'total' }, t('total'))),
    )))
  },
}
